:root {
  --bg-card: #0f1923;
  --bg-header: #162030;
  --bg-stat: #1a2a3a;
  --bg-panel: #162030;
  --bg-lower: #111d28;
  --accent-live: #00e676;
  --accent-temp: #ff7043;
  --accent-ph: #42a5f5;
  --accent-o2: #26c6da;
  --accent-ammonia: #ab47bc;
  --text-primary: #e8f4f8;
  --text-secondary: #7a9bb5;
  --text-label: #4a7a9b;
  --trend-up: #ff7043;
  --trend-down: #42a5f5;
  --trend-ok: #00e676;
  --bar-tilapia: #42a5f5;
  --bar-catfish: #ff7043;
  --bar-bass: #ab47bc;
  --bed-active-bg: #1a3a2a;
  --bed-active-border: #00e676;
  --bed-harvest-bg: #3a2a10;
  --bed-harvest-border: #ffb300;
  --bed-empty-bg: #1e2a35;
  --bed-empty-border: #4a7a9b;
  --border-subtle: #1e3048;
  --badge-bg: #00e676;
  --badge-text: #0a1510;
}

.monitor {
  background: var(--bg-card);
  border-radius: 12px;
  border: 1px solid var(--border-subtle);
  width: 476px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.monitor-header {
  background: var(--bg-header);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 14px;
  border-bottom: 1px solid var(--border-subtle);
}

.header-left {
  display: flex;
  align-items: center;
  gap: 7px;
}

.status-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent-live);
}

.monitor-title {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0;
}

.header-right {
  display: flex;
  align-items: center;
  gap: 8px;
}

.system-badge {
  background: var(--badge-bg);
  color: var(--badge-text);
  font-size: 9px;
  font-weight: 800;
  padding: 2px 6px;
  border-radius: 3px;
  letter-spacing: 0.08em;
}

.last-updated {
  font-size: 10px;
  color: var(--text-label);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
  padding: 10px 12px;
}

.stat-card {
  background: var(--bg-stat);
  border-radius: 8px;
  padding: 8px 7px;
  display: flex;
  flex-direction: column;
  gap: 3px;
  border: 1px solid var(--border-subtle);
}

.stat-icon {
  font-size: 14px;
  line-height: 1;
}

.stat-info {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.stat-label {
  font-size: 9px;
  color: var(--text-label);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.stat-value {
  font-size: 16px;
  font-weight: 700;
  line-height: 1.1;
}

.stat-temp .stat-value { color: var(--accent-temp); }
.stat-ph .stat-value { color: var(--accent-ph); }
.stat-oxygen .stat-value { color: var(--accent-o2); }
.stat-ammonia .stat-value { color: var(--accent-ammonia); }

.stat-unit {
  font-size: 9px;
  font-weight: 500;
  margin-left: 1px;
  color: var(--text-secondary);
}

.stat-trend {
  font-size: 9px;
  font-weight: 600;
}

.trend-up { color: var(--trend-up); }
.trend-down { color: var(--trend-down); }
.trend-ok { color: var(--trend-ok); }

.lower-section {
  background: var(--bg-lower);
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  padding: 8px 12px 10px;
  border-top: 1px solid var(--border-subtle);
}

.fish-panel,
.grow-panel {
  background: var(--bg-panel);
  border-radius: 8px;
  padding: 8px 10px;
  border: 1px solid var(--border-subtle);
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.panel-title {
  font-size: 10px;
  font-weight: 700;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.07em;
  margin: 0;
}

.fish-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.fish-item {
  display: flex;
  align-items: center;
  gap: 5px;
}

.fish-name {
  font-size: 10px;
  color: var(--text-secondary);
  width: 40px;
  flex-shrink: 0;
}

.fish-bar-track {
  flex: 1;
  height: 4px;
  background: var(--border-subtle);
  border-radius: 2px;
  overflow: hidden;
}

.fish-bar {
  height: 100%;
  border-radius: 2px;
}

.bar-tilapia { width: 84%; background: var(--bar-tilapia); }
.bar-catfish { width: 36%; background: var(--bar-catfish); }
.bar-bass    { width: 22%; background: var(--bar-bass); }

.fish-count {
  font-size: 10px;
  font-weight: 700;
  color: var(--text-primary);
  width: 18px;
  text-align: right;
}

.grow-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 5px;
}

.grow-bed {
  border-radius: 6px;
  padding: 5px 7px;
  display: flex;
  flex-direction: column;
  gap: 1px;
  border-width: 1px;
  border-style: solid;
}

.bed-active {
  background: var(--bed-active-bg);
  border-color: var(--bed-active-border);
}

.bed-harvest {
  background: var(--bed-harvest-bg);
  border-color: var(--bed-harvest-border);
}

.bed-empty {
  background: var(--bed-empty-bg);
  border-color: var(--bed-empty-border);
}

.bed-label {
  font-size: 9px;
  font-weight: 800;
  color: var(--text-label);
  letter-spacing: 0.06em;
}

.bed-crop {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-primary);
}

.bed-harvest .bed-crop { color: #ffb300; }
.bed-empty .bed-crop { color: var(--text-label); }
